insert into question_bank_stages (id, lang, position, icon, title) values (1, 'en', 0, '🧭', 'Stage 1 — HR & Motivation');
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (1, 1, 0, 'Walk me through your background and why you moved into test automation.', 'Tell it as a trajectory, not a CV read-out — what pulled you toward automation, and what you own now.', ARRAY['Structure it in three beats: where you started, the moment automation became the obvious lever, and what you own today. Two minutes, not ten.', 'Anchor the pivot in a concrete pain — a regression pass that took three days by hand, a release that slipped because manual sign-off could not keep up. Concrete beats abstract every time.', 'Land on scope and stack: what you automate now (UI, API, CI), which tools, how big the suite and the team are.', 'Close with direction — what you want to do more of — so the interviewer can connect your story to the role they are actually filling.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (2, 1, 1, 'Why are you leaving your current role, and what are you looking for next?', 'Answer forwards, not backwards: what you are moving toward, never what you are escaping.', ARRAY['Frame it as a growth ceiling rather than a grievance: "I took the suite from nightly-manual to a 9-minute PR gate, and the next step I want does not exist there" is both credible and safe.', 'Never criticise people or the employer. Interviewers silently extrapolate how you will talk about them a year from now.', 'Be specific about what you want next — ownership of a test strategy, deeper CI work, LLM feature testing — and tie it to something in their job description.', 'Keep one honest, neutral fact ready if pressed (reorg, project ended, contract, relocation). Vagueness reads as concealment; a plain fact closes the topic.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (3, 1, 2, 'Tell me about a project you are proud of — what was your specific contribution?', 'STAR, and the emphasis is on "specific": say I, not we, and finish with a number.', ARRAY['Situation and Task in two sentences. Spend the bulk of your answer on Action — that is the part being assessed.', 'Use "I" deliberately. This question exists to separate the people who did the work from the people who were standing nearby.', 'Quantify the Result: runtime cut from 40 minutes to 9, escaped defects down a third, flaky rate from 12% to under 1%. A number makes the story checkable.', 'Add one thing you would do differently now. Self-awareness reads as seniority; a flawless story reads as rehearsed.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (4, 1, 3, 'Describe a conflict with a developer over a bug. How did you resolve it?', 'They are testing evidence and tone, not who won.', ARRAY['Pick a real disagreement with a professional resolution. "I have never had one" reads as either dishonest or disengaged.', 'Show that you led with evidence: a reproducible case, logs, a video, the exact build and environment — moving the conversation from opinion to data.', 'Show that you separated correctness from severity. Whether it is a bug and whether it blocks the release are two different conversations, and the second one belongs to the product owner.', 'End with the relationship intact and something systemic changed: a bug-report template, a triage rule, a tightened definition of done.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (5, 1, 4, 'Where do you see QA automation heading in the next few years?', 'Show that you are current without the hype — name a shift, then say what it demands of testers.', ARRAY['Name concrete shifts: testing moving into the pipeline as a gate rather than a phase, API and contract tests carrying load that UI tests used to, and AI assisting with test generation and failure triage.', 'Say what does not change: someone still has to decide what "correct" means, own the risk model and design the oracle. Tooling moves fast; judgment does not.', 'Be honest about the new surface — LLM-backed features need evaluation sets, non-determinism budgets and safety tests. That is a genuinely new skill, not a rebranded old one.', 'Finish with what you are doing about it: something you have actually read, built or broken. Opinions are cheap; a side project is evidence.']::text[]);
insert into question_bank_items (id, stage_id, position, question, hint, answer) values (6, 1, 5, 'Tell me about yourself.', 'A 60-second pitch aimed at this role, not your life story.', ARRAY['Give three beats: what you do now, one concrete proof of impact, and why this role is the next step. Present, past-as-evidence, future.', 'Tailor it to the job description — lead with the part of your experience that matches what they are hiring for, and drop the rest.', 'Rehearse it to a minute. Rambling here sets the tone for the whole interview; a crisp answer buys you goodwill for the hard questions later.']::text[]);